lab.solution:
results = {
    "model_a": {"train": 0.99, "test": 0.61},
    "model_b": {"train": 0.58, "test": 0.55},
    "model_c": {"train": 0.90, "test": 0.87},
}

gaps = {}
diagnosis = {}
for name, scores in results.items():
    gap = round(scores["train"] - scores["test"], 2)
    gaps[name] = gap
    if gap > 0.10:
        diagnosis[name] = "overfit"
    elif scores["test"] < 0.70:
        diagnosis[name] = "underfit"
    else:
        diagnosis[name] = "well-generalised"
    print(f"{name}: train {scores['train']}, test {scores['test']}, gap {gaps[name]} -> {diagnosis[name]}")

fixes = {
    "model_a": "use a simpler model or collect more training data so it cannot memorise the examples",
    "model_b": "use a more complex model or add more features so it can learn the real pattern",
}

candidates = [name for name in results if diagnosis[name] != "overfit"]
chosen_model = max(candidates, key=lambda name: results[name]["test"])
print("Deploy:", chosen_model)
